using Godot;
using DarkColony.Original;
using System.Text.Json;
namespace DarkColony.Viewer;
public partial class Viewer {
 async Task UiClick(string id){QueueRedraw();await ToSignal(RenderingServer.Singleton,RenderingServer.SignalName.FramePostDraw);await NativeMouse(MouseButton.Left,missionHits.Single(h=>h.Id==id).Rect.GetCenter());}
 async Task UiCapture(string name){await MissionCapture(name);File.WriteAllText(Path.Combine(output,name+"-ui.json"),JsonSerializer.Serialize(new{mode="controlled UI fixture; not a mission completion",ui,camera=new[]{camera.X,camera.Y},zoom,missionPanel,targetMode,selection=NativeSelected().Select(e=>e.Identity),hits=missionHits.Select(h=>new{h.Id,h.Enabled,h.Help,rect=new[]{h.Rect.Position.X,h.Rect.Position.Y,h.Rect.Size.X,h.Rect.Size.Y}}),music=missionMusic==null?null:new{missionMusic.Track,missionMusic.Frame,missionMusic.Starts},units=nativeWorld.Entities.Where(e=>e.Living&&NativeVisible(e)).Select(e=>new{e.Identity,e.State,e.X,e.Z,e.Angle,sequence=e.Body.Set?.Name,frame=e.Body.Frame,marker=new[]{MarkerOffset(e).X,MarkerOffset(e).Y}})},new JsonSerializerOptions{WriteIndented=true}));}
 async Task VerifyMissionInterface(){
  missionHarnessManual=true;
  void Advance(int n){for(int i=0;i<n;i++){RememberNativePositions();mission.SetClock(mission.Milliseconds+66);mission.Step();DispatchMissionSounds();}nativeAccumulator=0;}
  Advance(180);await UiCapture("01-no-selection");
  Check(!missionHits.Single(h=>h.Id=="move").Enabled&&!missionHits.Single(h=>h.Id=="inspire").Enabled,"commands unavailable without selection");
  var warrior=nativeWorld.Entities.First(e=>e.Living&&e.Type==8&&e.Owner==0);await NativeMouse(MouseButton.Left,UnitHitRect(warrior).GetCenter());Check(NativeSelected().Any(e=>e==warrior),"click actual visible warrior artwork selects it");await UiCapture("02-single");
  int orders=nativeWorld.Events.Count(e=>e.Kind=="order");await UiClick("move");Check(targetMode=="move"&&nativeWorld.Events.Count(e=>e.Kind=="order")==orders,"Move button captures click without a world order");await UiCapture("03-targeting");await Send(Key.Escape);Check(targetMode==""&&missionPanel=="","Escape cancels target before menu");
  await SelectWholeSquad();Check(NativeSelected().Count()>=6,"selection drag selects squad and stationary CENT");zoom=2;await UiCapture("03-group");await Send(Key.Tab);await UiCapture("04-commander");
  var commander=NativeSelected().Single();commander.Energy=64;await UiClick("inspire");Advance(45);Check(nativeWorld.Events.Any(e=>e.Kind=="inspire"),"Inspire button issues real native ability");await UiCapture("05-inspire");
  await UiClick("menu");long held=nativeWorld.Tick;long audioFrame=missionMusic!.Frame;missionHarnessManual=false;missionWall=mission.Milliseconds/1000d;await ToSignal(GetTree().CreateTimer(.6),SceneTreeTimer.SignalName.Timeout);missionHarnessManual=true;Check(nativeWorld.Tick>held&&missionMusic.Frame>audioFrame,"menu does not pause simulation or original music");await UiCapture("06-menu");
  await UiClick("options");float gain=musicVolume;await UiClick("music-");Check(musicVolume<gain,"music option changes existing mixer gain");await UiClick("music+");await UiCapture("07-options");await Send(Key.Escape);
  await UiClick("objectives");await UiCapture("08-objectives");await Send(Key.Tab);Check(focusedUi=="close","modal Tab focuses available control");await Send(Key.Enter);Check(missionPanel=="","focused Enter closes modal");
  foreach(float scale in new[]{.75f,1f,1.125f,1.25f,1.5f}){ui=scale;await UiCapture("scale-"+scale.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture));Check(missionHits.All(h=>GetViewportRect().Encloses(h.Rect)),"UI hitboxes stay inside viewport at scale "+scale);await UiClick("stop");Check(nativeWorld.Events.Last(e=>e.Kind=="order").Value==(int)OriginalOrder.Stop,"scaled Stop hitbox dispatches exact command "+scale);}
  ui=Math.Clamp(GetViewportRect().Size.Y/1080,1,1.5f);await UiCapture("scale-restored");
  orders=nativeWorld.Events.Count(e=>e.Kind=="order");var selectedIds=nativeSelection.ToArray();
  var buttonPoint=missionHits.Single(h=>h.Id=="move").Rect.GetCenter();var worldPoint=NativeArea.GetCenter();
  Input.ParseInputEvent(new InputEventMouseButton{ButtonIndex=MouseButton.Left,Position=NativeWindowPoint(buttonPoint),Pressed=true});await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
  Input.ParseInputEvent(new InputEventMouseButton{ButtonIndex=MouseButton.Left,Position=NativeWindowPoint(worldPoint),Pressed=false});await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
  Check(targetMode==""&&!nativeSelecting&&nativeSelection.SetEquals(selectedIds)&&nativeWorld.Events.Count(e=>e.Kind=="order")==orders,"drag from command button into world neither selects nor orders");
  Input.ParseInputEvent(new InputEventMouseButton{ButtonIndex=MouseButton.Left,Position=NativeWindowPoint(worldPoint),Pressed=true});await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
  Input.ParseInputEvent(new InputEventMouseButton{ButtonIndex=MouseButton.Left,Position=NativeWindowPoint(buttonPoint),Pressed=false});await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
  Check(!nativeSelecting&&nativeSelection.SetEquals(selectedIds),"world selection drag ending over UI cancels cleanly");
  var previousSize=GetWindow().ContentScaleSize;GetWindow().ContentScaleSize=new(1600,900);await UiCapture("resize-1600x900");await UiClick("stop");Check(missionHits.All(h=>GetViewportRect().Encloses(h.Rect)),"resized viewport redraws aligned hitboxes");GetWindow().ContentScaleSize=previousSize;await UiCapture("resize-restored");
  orders=nativeWorld.Events.Count(e=>e.Kind=="order");await NativeMouse(MouseButton.Left,MiniMapRect.End-new Vector2(1,1));Check(nativeWorld.Events.Count(e=>e.Kind=="order")==orders,"minimap click cannot issue world order");await UiCapture("09-minimap-edge");
  zoom=2;await Send(Key.Tab);var enemy=nativeWorld.Spawn(0,1,new(commander.Cell.X+3,commander.Cell.Z),"diagnostic/ui/enemy");nativeWorld.RefreshSight();await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);var enemyPoint=UnitHitRect(enemy).GetCenter();missionPointer=enemyPoint;Check(UiHover(enemyPoint)==enemy,"visible enemy hover uses rendered artwork");await UiCapture("10-enemy-hover");var cent=nativeWorld.Entities.First(e=>e.Owner==0&&e.Type==89);var centCell=cent.Cell;nativeSelection.Add((cent.Slot,cent.Incarnation));await UiClick("attack");await NativeMouse(MouseButton.Left,enemyPoint);Check(nativeWorld.Events.Last(e=>e.Kind=="order").Other==enemy.Slot,"attack mode selects visible enemy target");Advance(20);Check(cent.Cell==centCell,"stationary CENT survives explicit mixed-selection attack without moving");await UiCapture("11-attack");
  nativeWorld.Sight.ClearCurrent();miniTick=-100;await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);Check(UiHover(enemyPoint)==null,"hidden enemy is absent from hover and targeting");await UiCapture("12-hidden");nativeWorld.RefreshSight();
  nativeSelection.Clear();nativeSelection.Add((warrior.Slot,warrior.Incarnation));warrior.State=10;await UiCapture("13-death-selection");Check(!NativeSelected().Any()&&nativeSelection.Count==0,"death clears selection and status");
  await Send(Key.R);Check(missionBriefing&&missionPanel==""&&targetMode==""&&nativeSelection.Count==0,"restart clears UI input state");await UiCapture("14-briefing-restart");await UiClick("brief-down");await UiCapture("15-briefing-scroll");await UiClick("begin");Advance(180);await SelectWholeSquad();zoom=2;await Send(Key.Tab);
  await UiClick("move");await ClickNativeCell(MouseButton.Left,new(28,20));missionWall=mission.Milliseconds/1000d;missionHarnessManual=false;
  var trace=new List<object>();var mover=NativeSelected().Single();int startX=mover.X,startZ=mover.Z;var cursorFrames=new HashSet<int>();
  for(int i=0;i<120;i++){await ToSignal(GetTree().CreateTimer(1d/30),SceneTreeTimer.SignalName.Timeout);cursorFrames.Add(cursorAnimation.Frame);trace.Add(new{frame=i,wall=Time.GetTicksMsec(),nativeWorld.Tick,cursor=new{sequence=cursorAnimation.Set?.Name,cursorAnimation.Frame,cursorAnimation.Delay},confirmation=new{orderAnimation.Mode,orderAnimation.Frame},units=NativeSelected().Select(e=>new{e.Identity,e.X,e.Z,e.Angle,e.State,sequence=e.Body.Set?.Name,frame=e.Body.Frame,delay=e.Body.Delay,screen=new[]{(NativeRenderPosition(e).Body*zoom+NativeOffset).X,(NativeRenderPosition(e).Body*zoom+NativeOffset).Y}}).ToArray()});}
  Check(mover.X!=startX||mover.Z!=startZ,"continuous capture contains actual commanded movement");Check(cursorFrames.Count==3,"movement cursor displays all three original FIN frames");
  missionHarnessManual=true;File.WriteAllText(Path.Combine(output,"continuous-ui-trace.json"),JsonSerializer.Serialize(trace));Check(orderAnimation.Mode==2,"original confirmation animation terminates at FIN end");await UiCapture("16-movement");
  await Send(Key.R);await Send(Key.Enter);nativeWorld.Deaths[1,82]=11;nativeWorld.NearbyCommanderKills[0]=10;nativeWorld.Kills[0,73]=80;Advance(24);mission.SetClock(mission.Outcome!.Deadline+1);await ToSignal(GetTree().CreateTimer(1),SceneTreeTimer.SignalName.Timeout);Check(missionVideo is {Visible:true}&&missionMusic is {Active:false},"diagnostic success transitions to outcome movie and stops mission music");await UiCapture("17-outcome-movie");await Send(Key.Enter);await ToSignal(GetTree().CreateTimer(2),SceneTreeTimer.SignalName.Timeout);await UiCapture("18-success-rewards");await UiClick("restart");Check(missionBriefing&&!rewardsVisible&&missionVideo==null,"outcome Replay clears rewards and movie");
  await UiClick("begin");nativeWorld.Deaths[0,73]=1;Advance(24);mission.SetClock(mission.Outcome!.Deadline+1);await ToSignal(GetTree().CreateTimer(.5),SceneTreeTimer.SignalName.Timeout);await Send(Key.Enter);await UiCapture("19-failure");await UiClick("restart");await UiCapture("20-final-briefing");
 }
}
